def validate_results(raw):
    missing = REQUIRED - set(raw.columns)
    if missing:
        raise ValueError("필수 컬럼이 없습니다: " + ", ".join(sorted(missing)))
    df = raw.copy()
    df["date"] = pd.to_datetime(df["date"], errors="coerce").dt.strftime("%Y-%m-%d")
    if df["date"].isna().any() or df[["code","name","market"]].isna().any().any():
        raise ValueError("날짜·종목·시장 정보에 읽을 수 없는 값이 있습니다.")
    df["code"] = df["code"].astype(str).str.strip().str.zfill(6)
    if df.duplicated(["date","code"]).any():
        raise ValueError("같은 날짜·종목의 결과가 중복돼 있습니다.")
    for col in ["price_alert","volume_alert","both_alert","market_alert"]:
        if col in df:
            values = df[col].astype(str).str.strip().str.lower()
            if not values.isin(["true","false","1","0"]).all():
                raise ValueError(f"{col}에는 True/False 값이 필요해요.")
            df[col] = values.isin(["true","1"])
    for col in ["alpha","market_part","sector_part","stock_return","expected_return",
                "price_residual","price_z","volume_z","volume_ratio_40d"]:
        if col in df:
            df[col] = pd.to_numeric(df[col], errors="coerce")
    if df.empty:
        raise ValueError("분석 결과가 비어 있습니다.")
    return df.sort_values(["date","code"]).reset_index(drop=True)

def get_results():
    path = DATA / "daily_results.csv"
    if path.is_file():
        try:
            return validate_results(pd.read_csv(path, dtype={"code":str}))
        except (ValueError, OSError) as exc:
            st.error(f"분석 결과를 읽지 못했어요: {exc}")
    else:
        st.info("분석 결과 CSV를 연결해주세요. 프로젝트 폴더에 저장하거나 아래에서 업로드할 수 있어요.")
    upload = st.file_uploader("daily_results.csv 선택", type=["csv"])
    if upload:
        try:
            return validate_results(pd.read_csv(upload, dtype={"code":str}))
        except (ValueError, OSError) as exc:
            st.error(str(exc))
    st.caption("기본 위치: app.py와 같은 폴더의 stored_data/daily_results.csv")
    st.stop()

def load_favorites(codes):
    try:
        with sqlite3.connect(PREF) as conn:
            conn.execute("CREATE TABLE IF NOT EXISTS preferences (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
            record = conn.execute("SELECT value FROM preferences WHERE key=?", ("favorites",)).fetchone()
            if record is None:
                conn.execute("INSERT INTO preferences VALUES (?,?)", ("favorites",json.dumps(codes)))
                return set(codes)
            return set(json.loads(record[0])) & set(codes)
    except (sqlite3.Error, ValueError, TypeError):
        st.warning("저장된 관심 종목을 읽지 못해 기본 목록을 사용해요.")
        return set(codes)

def toggle_favorite(code):
    selected = set(st.session_state.favorites)
    selected.remove(code) if code in selected else selected.add(code)
    st.session_state.favorites = selected
    st.session_state.notification_open = False
    try:
        with sqlite3.connect(PREF) as conn:
            conn.execute("INSERT OR REPLACE INTO preferences VALUES (?,?)",
                         ("favorites",json.dumps(sorted(selected))))
    except sqlite3.Error:
        st.session_state.preference_warning = True

def navigate(screen, code=None):
    screen = "list" if screen in {"themes","favorites"} else screen
    previous = st.session_state.get("screen","home")
    if screen in {"detail","news"}:
        if previous not in {"detail","news"}:
            st.session_state.origin_menu = "list" if previous=="home" else previous
        if screen=="news" and previous!="news":
            st.session_state.news_parent = "detail" if previous=="detail" else st.session_state.get("origin_menu","list")
    st.session_state.screen = screen
    st.session_state.notification_open = False
    if code is not None:
        st.session_state.selected_code = code
    st.query_params["view"] = screen
    st.query_params["date"] = st.session_state.analysis_date
    if screen in {"detail","news"}:
        st.query_params["code"] = st.session_state.selected_code
        st.query_params["from"] = st.session_state.get("origin_menu","list")
        if screen=="news":
            st.query_params["parent"] = st.session_state.get("news_parent","list")
        elif "parent" in st.query_params:
            del st.query_params["parent"]
    else:
        for key in ["code","from","parent"]:
            if key in st.query_params:
                del st.query_params[key]

def active_menu():
    screen = st.session_state.screen
    return st.session_state.get("origin_menu","list") if screen in {"detail","news"} else "list" if screen=="home" else screen

def choose_menu(screen):
    st.session_state.stock_search = ""
    navigate(screen)

def change_date():
    # Changing the reference date preserves the visible page and selected stock.
    screen = st.session_state.screen
    navigate(screen,st.session_state.selected_code if screen in {"detail","news"} else None)

def return_from_news():
    screen = st.session_state.get("news_parent","list")
    navigate(screen,st.session_state.selected_code if screen=="detail" else None)

def dismiss_notification():
    st.session_state.notification_open = False

def dot(day):
    return str(day).replace("-",".")

def date_alert_flags(df,favorites):
    records = df[df["code"].isin(favorites)]
    if "decision_status" in records:
        records = records[records["decision_status"].eq("OK")]
    flags = records.groupby("date")[["price_alert","volume_alert"]].any()
    return {day:(bool(row["price_alert"]),bool(row["volume_alert"]))
            for day,row in flags.iterrows()}

def move_calendar_month(offset):
    month = date.fromisoformat(st.session_state.calendar_month)
    shifted = month.year*12+month.month-1+offset
    st.session_state.calendar_month = date(shifted//12,shifted%12+1,1).isoformat()

def select_calendar_date(day):
    st.session_state.analysis_date = day
    st.session_state.calendar_month = day[:7]+"-01"
    st.session_state.analysis_calendar = False
    change_date()

def trading_calendar(df,days):
    selected = st.session_state.analysis_date
    earliest,latest = date.fromisoformat(min(days)),date.fromisoformat(max(days))
    first,last = earliest.replace(day=1),latest.replace(day=1)
    if "calendar_month" not in st.session_state:
        st.session_state.calendar_month = selected[:7]+"-01"
    month = date.fromisoformat(st.session_state.calendar_month)
    month = max(first,min(last,month))
    st.session_state.calendar_month = month.isoformat()
    flags = date_alert_flags(df,st.session_state.favorites)
    available = set(days)
    st.markdown('<div class="calendar-label">분석 기준 거래일</div>',unsafe_allow_html=True)
    with st.container(key="calendar_control"):
        with st.popover(f"📅 {dot(selected)}",key="analysis_calendar",width="stretch"):
            with st.container(key="calendar_grid"):
                with st.container(key="calendar_month_nav"):
                    previous,title,following = st.columns([1,5,1],gap="small")
                    with previous:
                        st.button("‹",key="calendar_prev",help="이전 달",disabled=month<=first,
                                  on_click=move_calendar_month,args=(-1,),width="stretch")
                    with title:
                        st.markdown(f'<div class="calendar-month">{month.year}.{month.month:02d}</div>',unsafe_allow_html=True)
                    with following:
                        st.button("›",key="calendar_next",help="다음 달",disabled=month>=last,
                                  on_click=move_calendar_month,args=(1,),width="stretch")
                for column,label in zip(st.columns(7,gap="small"),["일","월","화","수","목","금","토"]):
                    with column:
                        st.markdown(f'<div class="calendar-weekday">{label}</div>',unsafe_allow_html=True)
                styles = []
                for week in calendar.Calendar(firstweekday=6).monthdayscalendar(month.year,month.month):
                    for column,number in zip(st.columns(7,gap="small"),week):
                        with column:
                            if not number:
                                st.markdown('<div class="calendar-blank"></div>',unsafe_allow_html=True)
                                continue
                            day = date(month.year,month.month,number).isoformat()
                            price,volume = flags.get(day,(False,False))
                            key = "calendar_day_"+day.replace("-","_")
                            if price or volume:
                                color = "#e33750" if price else "#f3bd36"
                                shadow = "box-shadow:8px 0 0 #f3bd36;" if price and volume else ""
                                position = "calc(50% - 7px)" if price and volume else "calc(50% - 3px)"
                                styles.append(f'.st-key-{key} button::after{{content:"";position:absolute;bottom:3px;left:{position};width:6px;height:6px;border-radius:50%;background:{color};{shadow}}}')
                            help_text = dot(day)+(" · 주가 경보" if price else "")+(" · 거래량 경보" if volume else "")
                            st.button(str(number),key=key,help=help_text if day in available else "분석 데이터가 없는 날",
                                      disabled=day not in available,on_click=select_calendar_date,args=(day,),
                                      type="primary" if day==selected else "secondary",width="stretch")
                if styles:
                    st.markdown('<style>'+''.join(styles)+'</style>',unsafe_allow_html=True)
            st.caption("분석 데이터가 있는 거래일을 선택하세요.")
    st.markdown('<div class="date-alert-legend"><span><i class="date-alert-dot price"></i>주가 경보</span><span><i class="date-alert-dot volume"></i>거래량 경보</span></div>',unsafe_allow_html=True)
    st.caption("날짜의 점은 현재 관심 종목 기준이에요.")

def sidebar_navigation(df,catalog,days,daily):
    selected_menu = active_menu()
    with st.sidebar:
        trading_calendar(df,days)
        st.markdown('<div class="sidebar-title">반도체 종목 탐색</div>',unsafe_allow_html=True)
        with st.expander("반도체",expanded=False,key="semiconductor_theme"):
            theme_overview(catalog,daily,st.session_state.analysis_date,show_title=False)
        st.button("경보 목록",key="nav_list",on_click=choose_menu,args=("list",),
                  width="stretch",type="primary" if selected_menu=="list" else "secondary")
        st.text_input("종목 검색",key="stock_search",placeholder="종목명 또는 코드를 입력하세요",on_change=dismiss_notification)
        st.markdown(f'<div class="sidebar-stocks-title">반도체 · {len(catalog)}개 종목</div>',unsafe_allow_html=True)
        for _,row in catalog.iterrows():
            opened = st.session_state.screen in {"detail","news"} and st.session_state.selected_code==row["code"]
            with st.container(key=f'side_row_{row["code"]}'):
                stock,heart = st.columns([5,1],gap="small")
                with stock:
                    st.button(f'{row["code"]} · {row["name"]}',key=f'side_stock_{row["code"]}',
                              on_click=open_search_detail,args=(row["code"],),width="stretch",
                              type="primary" if opened else "secondary")
                with heart:
                    favorite_button(row["code"],"side")

def fmt(value, unit="%p"):
    if pd.isna(value) or not math.isfinite(float(value)):
        return "데이터 없음"
    return f"{float(value)*100:+.2f}{unit}"

def tone(value):
    return "neutral" if pd.isna(value) else "up" if value>0 else "down" if value<0 else "neutral"

def favorite_button(code,scope):
    liked = code in st.session_state.favorites
    heart_key = f"heart_{scope}_{code}"
    label = "관심 종목 해제" if liked else "관심 종목 등록"
    if scope=="side":
        # Native heart text stays visible inside the shared stock pill even if
        # a browser does not apply CSS background images to Streamlit widgets.
        st.button("♥" if liked else "♡",key=heart_key,help=label,
                  on_click=toggle_favorite,args=(code,))
        return
    # Keep the SVG dimensions fixed in both states to prevent squeezing.
    fill = "#ff3b55" if liked else "none"
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78Z" fill="{fill}" stroke="#ff3b55" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>'
    st.markdown(f'<style>.stApp .st-key-{heart_key} button{{background-image:url("data:image/svg+xml,{quote(svg,safe="")}")!important;}}</style>',unsafe_allow_html=True)
    label = "관심 종목 해제" if liked else "관심 종목 등록"
    st.button(label,key=heart_key,help=label,on_click=toggle_favorite,args=(code,))

def header(row, scope, clickable=True, show_cap=True):
    with st.container(key=f"stock_header_{scope}_{row['code']}"):
        title, heart = st.columns([6,1],gap="small")
        with title:
            if clickable:
                st.button(row["name"],key=f"open_{scope}_{row['code']}",
                          on_click=open_search_detail if scope=="search" else navigate,
                          args=(row["code"],) if scope=="search" else ("detail",row["code"]))
            else:
                st.markdown(f'<div class="page-title">{escape(row["name"])}</div>',unsafe_allow_html=True)
            market = {"KOSPI":"코스피","KOSDAQ":"코스닥"}.get(row["market"],row["market"])
            market_class = {"KOSPI":"kospi","KOSDAQ":"kosdaq"}.get(row["market"],"other")
            st.markdown(f'<span class="code">{escape(row["code"])}</span><span class="market {market_class}">{escape(market)}</span><span class="theme">반도체</span>',unsafe_allow_html=True)
            if show_cap:
                cap = row.get("market_cap")
                meta = f"시가총액 {float(cap)/1e12:,.2f}조원" if pd.notna(cap) else "기준일 시가총액 미연결"
                st.markdown(f'<div class="stock-meta">{escape(meta)}</div>',unsafe_allow_html=True)
        with heart:
            favorite_button(row["code"],scope)

def alert_status_markup(row):
    price = row.get("price_alert",False)
    volume = row.get("volume_alert",False)
    price = bool(price) if pd.notna(price) else False
    volume = bool(volume) if pd.notna(volume) else False
    warning = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10.3 4.2a2 2 0 0 1 3.4 0L21 17a2 2 0 0 1-1.7 3H4.7A2 2 0 0 1 3 17Z"/><path d="M12 8v5"/><circle cx="12" cy="16" r=".7" fill="currentColor" stroke="none"/></svg>'
    bars = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M5 19V12M12 19V5M19 19V9"/></svg>'
    quiet = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></svg>'
    chips = []
    missing = "date" in row and pd.isna(row["date"])
    pending = "decision_status" in row and row["decision_status"]!="OK"
    if missing or pending:
        label = "분석 결과 없음" if missing else "판정 확인 필요"
        return f'<div class="alert-status"><span class="alert-chip quiet">{warning}{label}</span></div>'
    if price:
        chips.append(f'<span class="alert-chip price" title="선택 기준일의 주가 경보">{warning}주가 경보</span>')
    if volume:
        chips.append(f'<span class="alert-chip volume" title="선택 기준일의 거래량 경보">{bars}거래량 경보</span>')
    if not chips:
        chips.append(f'<span class="alert-chip quiet">{quiet}경보 없음</span>')
    return '<div class="alert-status">'+''.join(chips)+'</div>'

def alert_status(row):
    st.markdown(alert_status_markup(row),unsafe_allow_html=True)

def metrics(row):
    actual,residual = row["stock_return"],row["price_residual"]
    residual_note = ""
    if pd.notna(residual):
        direction = "높은" if residual>0 else "낮은" if residual<0 else "같은"
        residual_note = f'<div class="metric-note">{escape(f"시장·업종을 고려한 모형 예상보다 {abs(residual)*100:.2f}%p {direction} 수익률이에요.")}</div>'
    alpha_note = f"알파 {fmt(row['alpha'])} · 시장·업종 기여와 알파의 합이 모형 예상 등락률이에요."
    st.markdown(f'<div class="metrics"><div class="metric"><div class="label">당일 등락률</div><div class="value {tone(actual)}">{fmt(actual,"%")}</div></div><div class="metric emphasis"><div class="label">모형 예상 대비 이탈</div><div class="value {tone(residual)}">{fmt(residual)}</div>{residual_note}</div></div>',unsafe_allow_html=True)
    parts = [("시장 기여",row["market_part"],"%p"),("업종 기여",row["sector_part"],"%p"),
             ("모형 예상 등락률",row["expected_return"],"%")]
    cells = "".join(f'<div class="part"><div class="label">{label}</div><strong class="{tone(value)}">{fmt(value,unit)}</strong>'+
                    (f'<div class="metric-note">{escape(alpha_note)}</div>' if label=="모형 예상 등락률" else "")+'</div>' for label,value,unit in parts)
    st.markdown(f'<div class="contrib">{cells}</div>',unsafe_allow_html=True)

def render_chart(chart):
    chart = chart.configure(font=FONT_NAME).configure_axis(
        labelFont=FONT_NAME,titleFont=FONT_NAME,labelFontSize=13,titleFontSize=14,
        labelColor="#37313f",titleColor="#111")
    st.altair_chart(chart,width="stretch",theme=None)

def volume_metrics_markup(row):
    volume,ratio,z = row.get("volume"),row.get("volume_ratio_40d"),row.get("volume_z")
    values = [("당일 거래량",f"{volume:,.0f}주" if pd.notna(volume) else "데이터 없음"),
              ("40일 기준 거래량 배율",f"{ratio:.2f}배" if pd.notna(ratio) else "데이터 없음"),
              ("거래량 Z점수",f"{z:+.2f}" if pd.notna(z) else "데이터 없음")]
    cells = ''.join(f'<div class="part"><div class="label">{label}</div><strong>{value}</strong></div>' for label,value in values)
    return f'<div class="contrib volume-metrics">{cells}</div>'

def volume_metrics(row):
    st.markdown(volume_metrics_markup(row),unsafe_allow_html=True)
    if row.get("volume_alert",False):
        st.caption("거래량 경보 · FDS 분석 결과에서 거래량 경보로 판정됐어요.")

def emphasize_last_point(chart,history,field,unit,color="#7059ec",label_color="#4f3e96"):
    latest = history.loc[history[field].notna()].tail(1).copy()
    if latest.empty:
        return chart
    value = float(latest.iloc[0][field])
    latest["마지막 값"] = f"{value:,.0f}{unit}" if unit in {"원","주"} else f"{value:+.2f}{unit}"
    endpoint = alt.Chart(latest).encode(x=chart.encoding.x,y=chart.encoding.y,tooltip=chart.encoding.tooltip)
    point = endpoint.mark_point(size=115,filled=True,color=color,stroke="#fff",strokeWidth=2)
    below = value>=float(history[field].median())
    label = endpoint.mark_text(font=FONT_NAME,fontSize=14,fontWeight=700,color=label_color,
                               align="right",dx=-10,dy=12 if below else -12,
                               baseline="top" if below else "bottom").encode(text="마지막 값:N")
    return chart+point+label

def history_chart(df,code,day):
    history = df[(df["code"]==code)&(df["date"]<=day)].tail(20).copy()
    if history["price_residual"].notna().sum()<2:
        st.caption("추이를 표시할 분석 결과가 부족해요.")
        return
    history["거래일"] = history["date"]
    history["예상 대비 이탈 (%p)"] = history["price_residual"]*100
    order = history["거래일"].tolist()
    chart = alt.Chart(history).mark_line(color="#8066df",strokeWidth=2.7,point=True).encode(
        x=alt.X("거래일:O",sort=order,title=None,
            axis=alt.Axis(values=order[::4],labelExpr="substring(datum.label, 5, 7) + '/' + substring(datum.label, 8, 10)",labelAngle=0,grid=False)),
        y=alt.Y("예상 대비 이탈 (%p):Q",title=None,scale=alt.Scale(zero=True),axis=alt.Axis(format="+.2f")),
        tooltip=[alt.Tooltip("거래일:O",title="거래일"),alt.Tooltip("예상 대비 이탈 (%p):Q",format="+.2f")]
    ).properties(height=190)
    zero = alt.Chart(pd.DataFrame({"zero":[0]})).mark_rule(color="#d5d1e0",strokeDash=[3,3]).encode(y="zero:Q")
    st.markdown('<div class="chart-axis-label">예상 대비 이탈 (%p)</div>',unsafe_allow_html=True)
    render_chart(emphasize_last_point(chart,history,"예상 대비 이탈 (%p)","%p")+zero)
    st.caption(f"{dot(order[0])} ~ {dot(order[-1])} · {len(history)}거래일 · 날짜 눈금 4거래일 간격")
    st.caption("0선보다 위면 모형 예상보다 높은 수익률, 아래면 낮은 수익률이에요. 단위는 %p예요.")
    if len(history)<20:
        st.caption("확보된 분석 결과가 20거래일보다 적어요.")

def return_chart(df,code,day):
    history = df[(df["code"]==code)&(df["date"]<=day)].tail(20).copy()
    history["거래일"] = pd.to_datetime(history["date"])
    history["일별 수익률 (%)"] = history["stock_return"]*100
    st.caption("최근 20거래일 · 일별 수익률 (%) · 선택 기준일까지")
    if history["stock_return"].notna().sum()<2:
        st.caption("수익률 추이를 표시할 데이터가 부족해요.")
        return
    chart = alt.Chart(history).mark_line(color="#8066df",strokeWidth=2.5,point=True).encode(
        x=alt.X("거래일:T",title=None,axis=alt.Axis(format="%m/%d",grid=False,tickCount=4)),
        y=alt.Y("일별 수익률 (%):Q",title=None,scale=alt.Scale(zero=True)),
        tooltip=[alt.Tooltip("거래일:T",format="%Y.%m.%d"),alt.Tooltip("일별 수익률 (%):Q",format="+.2f")]
    ).properties(height=140)
    zero = alt.Chart(pd.DataFrame({"zero":[0]})).mark_rule(color="#d5d1e0",strokeDash=[3,3]).encode(y="zero:Q")
    render_chart(chart+zero)

def quiet_day(df,selected,day):
    if not st.session_state.favorites:
        st.info("하트를 눌러 관심 종목을 등록해주세요.")
        return
    st.info("선택한 기준일에는 관심 종목의 주가·거래량 경보가 없어요")
    st.markdown(f'<div class="date">{dot(day)} 정규장 마감 기준</div>',unsafe_allow_html=True)
    if selected.empty:
        st.caption("이 날짜에 표시할 관심 종목의 분석 결과가 없어요.")
    for _,row in sort_stocks(selected).iterrows():
        with st.container(key=f"card_quiet_{row['code']}"):
            header(row,"quiet")
            actual = row["stock_return"]
            # Keep both groups in one DOM layout so their spacing cannot collapse
            # between separate Streamlit Markdown elements.
            st.markdown(f'<div class="quiet-summary"><div class="metric"><div class="label">당일 수익률</div><div class="value {tone(actual)}">{fmt(actual,"%")}</div></div>{volume_metrics_markup(row)}</div>',unsafe_allow_html=True)
            closing_chart(st.session_state.daily_prices,row["code"],day)
            volume_chart(st.session_state.daily_volumes,df,row["code"],day,show_z=False)
            st.button("상세 보기 →",key=f"detail_quiet_{row['code']}",on_click=navigate,args=("detail",row["code"]),width="stretch")

def z_explanation(row=None):
    st.write("Z점수는 값이 평균에서 표준편차 몇 배만큼 떨어져 있는지 나타내요. 일반 Z점수는 (값 − 평균) ÷ 표준편차로 계산해요.")
    st.latex(r"Z = \frac{x-\mu}{\sigma}")
    st.write("예를 들어 +2.5는 평균보다 표준편차 2.5배 높은 값, −2.5는 2.5배 낮은 값이에요. 등락률 2.5%나 거래량 2.5배를 뜻하지 않아요.")
    st.write("주가 Z점수는 실제 수익률에서 모형 예상 수익률을 뺀 이탈값을 표준화한 값이에요. 거래량 Z점수는 코드에서 정의한 거래량 분석값을 표준화한 값이에요.")
    st.caption("수익률·거래량의 임계값은 모두 2.5예요. 평균·표준편차 계산 구간, 거래량 변환과 단측·양측 판정, 경계값 포함 여부는 모형 코드의 정의를 따라요.")
    if row is not None:
        for col,label in [("price_z","이 종목의 주가 Z점수"),("volume_z","이 종목의 거래량 Z점수")]:
            value = row.get(col)
            st.write(f"{label}: {value:+.2f}" if pd.notna(value) else f"{label}: 데이터 없음")
    st.caption("Z점수만으로 상승·하락 전망이나 뉴스의 인과관계를 판단할 수는 없어요.")

@st.dialog("Z점수 상세 설명",width="small")
def z_dialog(row):
    z_explanation(row)

def load_peer_materials():
    filenames = ["peer_sector_2025.csv", "peer_sector_guide.csv"]
    paths = [MARKET_CSV/name for name in filenames]
    if any(not path.is_file() for path in paths):
        return None, None
    try:
        peers = pd.read_csv(paths[0],dtype=str,keep_default_na=False)
        guide = pd.read_csv(paths[1],dtype=str,keep_default_na=False)
        if not {"category","name","code","business","revenue_share","analysis_year","source_url"} <= set(peers.columns):
            raise ValueError("비교군 명단의 필수 컬럼이 누락됐어요.")
        if not {"section","item","content","notes","analysis_year","source_url"} <= set(guide.columns):
            raise ValueError("비교군 설명의 필수 컬럼이 누락됐어요.")
        peers["code"] = peers["code"].str.strip().str.zfill(6)
        if peers.empty or guide.empty or peers["code"].duplicated().any() or not peers["code"].str.fullmatch(r"\d{6}").all():
            raise ValueError("비교군 명단이 비어 있거나 종목코드가 잘못됐어요.")
        if not peers["analysis_year"].eq("2025").all() or not guide["analysis_year"].eq("2025").all():
            raise ValueError("비교군 자료의 적용 연도를 확인해주세요.")
        return peers, guide
    except (OSError,ValueError) as exc:
        st.warning(f"산업 비교군 자료를 읽지 못했어요: {exc}")
        return None, None

def peer_table(view, height):
    # HTML text follows the same font as the rest of the page, including Korean cells.
    headings = ''.join(f'<th scope="col">{escape(str(column))}</th>' for column in view.columns)
    rows = []
    for values in view.itertuples(index=False,name=None):
        cells = ''.join(f'<td class="{"stock-code" if column=="종목코드" else ""}">{escape(str(value))}</td>' for column,value in zip(view.columns,values))
        rows.append(f'<tr>{cells}</tr>')
    st.markdown(f'<div class="peer-table-wrap" style="max-height:{int(height)}px"><table class="peer-table"><thead><tr>{headings}</tr></thead><tbody>{"".join(rows)}</tbody></table></div>',unsafe_allow_html=True)

