RESULT_PENDING = "현재 정보 제공 준비중"

def result_subject(value):
    # macOS filenames may contain decomposed Hangul. Compare canonical text,
    # while retaining the original Path for opening the actual files.
    normalized = unicodedata.normalize("NFC",str(value))
    return re.sub(r"\s+","",normalized).casefold()

def find_result_folder(row,day):
    # Resolve relative to app.py, so teammates need no Windows-specific path.
    root = ROOT / "result"
    subjects = {result_subject(row["name"]),str(row["code"]).zfill(6)}
    try:
        for folder in sorted(root.iterdir()):
            match = re.fullmatch(r"(.+)_(\d{8}|\d{4}-\d{2}-\d{2})",folder.name)
            if not folder.is_dir() or match is None:
                continue
            subject,stamp = match.groups()
            if result_subject(subject) in subjects and stamp.replace("-","")==day.replace("-",""):
                return folder
    except OSError:
        pass
    return None

def read_result_text(path):
    try:
        return path.read_text(encoding="utf-8-sig")
    except UnicodeDecodeError:
        return path.read_text(encoding="cp949")

def evidence_sources(payload,code,day):
    records = payload.get("evidence",[])
    if not isinstance(records,list) or any(not isinstance(record,dict) for record in records):
        raise ValueError("출처 자료의 형식을 확인해주세요.")
    publishers = {"biz.chosun.com":"조선비즈","yna.co.kr":"연합뉴스",
                  "sedaily.com":"서울경제","hankyung.com":"한국경제",
                  "dart.fss.or.kr":"DART","kind.krx.co.kr":"한국거래소"}
    grouped = {}
    for index,record in enumerate(records):
        source_type = str(record.get("source_type") or "").upper()
        kind = "disclosure" if source_type in {"DISCLOSURE","DART","공시"} else "news"
        url = str(record.get("source_url") or "").strip()
        try:
            parsed = urlparse(url)
            host = (parsed.hostname or "").lower()
            if parsed.scheme not in {"http","https"} or not host:
                url,host = "",""
        except ValueError:
            url,host = "",""
        source_id = str(record.get("source_id") or "").strip()
        # An article can support several claims: show its link only once.
        key = (kind,url or source_id or f"entry_{index}")
        if key not in grouped:
            source = str(record.get("source") or "").strip()
            if not source and host:
                source = next((name for domain,name in publishers.items()
                               if host==domain or host.endswith("."+domain)),host)
            if not source:
                source = "공시자료" if kind=="disclosure" else "뉴스자료"
            original_title = str(record.get("title") or record.get("report_name") or "").strip()
            event = str(record.get("event") or "").strip()
            grouped[key] = {"code":code,"date":day,"kind":kind,
                            "title":original_title or f"핵심 내용 · {event or source}",
                            "source":source,"published_at":str(record.get("published_at") or ""),
                            "url":url,"events":[],"contents":[]}
        event = str(record.get("event") or "").strip()
        if event and event not in grouped[key]["events"]:
            grouped[key]["events"].append(event)
        content = str(record.get("content") or "").strip()
        if content and content not in grouped[key]["contents"]:
            grouped[key]["contents"].append(content)
    return list(grouped.values())

def load_case_result(row,day):
    result = {"summary":"","paragraphs":[],"items":[],"issues":[]}
    folder = find_result_folder(row,day)
    if folder is None:
        return result
    evidence_path = folder / "evidence.json"
    payload = None
    if evidence_path.is_file():
        try:
            payload = json.loads(read_result_text(evidence_path))
            if not isinstance(payload,dict):
                raise ValueError("출처 자료의 형식을 확인해주세요.")
            code = str(row["code"]).zfill(6)
            if payload.get("stock_code") is not None and str(payload["stock_code"]).strip().zfill(6)!=code:
                raise ValueError("선택한 종목과 결과 자료의 종목이 달라요.")
            if payload.get("company") and result_subject(payload["company"])!=result_subject(row["name"]):
                raise ValueError("선택한 종목과 결과 자료의 종목이 달라요.")
            if payload.get("detection_time"):
                if not isinstance(payload["detection_time"],str):
                    raise ValueError("결과 자료의 탐지일을 확인해주세요.")
                detected = pd.to_datetime(payload["detection_time"],errors="coerce")
                if pd.isna(detected):
                    raise ValueError("결과 자료의 탐지일을 확인해주세요.")
                if detected.tzinfo is not None:
                    detected = detected.tz_convert("Asia/Seoul")
                if detected.strftime("%Y-%m-%d")!=day:
                    raise ValueError("선택한 기준일과 결과 자료의 탐지일이 달라요.")
        except (OSError,ValueError,TypeError) as exc:
            result["issues"].append(f"결과 자료를 확인해주세요: {exc}")
            # Do not display a summary from a mismatched or unreadable case.
            return result
    summary_path = next((path for path in [folder/"user_explanation.txt",folder/"user_explanation"]
                         if path.is_file()),None)
    if summary_path is not None:
        try:
            summary = read_result_text(summary_path).strip()
            # Paragraph IDs belong to the evidence mapping, not the prose UI.
            paragraphs = re.split(r"(?m)^\s*\[P\d+\]\s*",summary)
            result["paragraphs"] = [part.strip() for part in paragraphs if part.strip()]
            if len(result["paragraphs"])==1 and not re.search(r"(?m)^\s*\[P\d+\]",summary):
                result["paragraphs"] = [part.strip() for part in re.split(r"\n\s*\n",summary) if part.strip()]
            result["summary"] = "\n\n".join(result["paragraphs"])
        except (OSError,UnicodeError):
            result["issues"].append("설명문을 읽지 못했어요. 자료를 확인해주세요.")
    if payload is not None:
        try:
            result["items"] = evidence_sources(payload,str(row["code"]).zfill(6),day)
        except (ValueError,TypeError) as exc:
            result["issues"].append(str(exc))
    return result

def format_published_at(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}",raw):
        return raw
    timestamp = pd.to_datetime(raw.replace(" (KST)","+09:00"),errors="coerce")
    if pd.isna(timestamp):
        return raw
    if timestamp.tzinfo is not None:
        timestamp = timestamp.tz_convert("Asia/Seoul")
    return timestamp.strftime("%Y-%m-%d %H:%M:%S")

def format_confirmed_content(value):
    """Use present reporting verbs in the UI without changing past events."""
    reporting_verbs = {
        "전했다": "전하고 있다",
        "보도됐다": "보도되고 있다",
        "서술했다": "서술하고 있다",
    }
    return re.sub(
        r"(?<!\w)(전했다|보도됐다|서술했다)(?=[.!?。]|$)",
        lambda match: reporting_verbs[match.group(0)],
        str(value or ""),
    )

def sources(items,code,day,detail=False,heading="관련 뉴스·공시"):
    chosen = [i for i in items if str(i["code"]).zfill(6)==code and str(i["date"])==day]
    heading_class = "key-information-heading" if detail else "section-label"
    st.html(f'<div class="{heading_class}">{escape(heading)}</div>')
    if not chosen:
        st.markdown(f'<div class="placeholder">{RESULT_PENDING}</div>',unsafe_allow_html=True)
        return
    for kind,label in [("news","뉴스"),("disclosure","공시")]:
        group = [i for i in chosen if i["kind"]==kind]
        for item in group if detail else group[:2]:
            title = str(item["title"] if detail else item.get("short_title") or item["title"])
            if not detail and len(title)>44:
                title = title[:43].rstrip()+"…"
            url = str(item.get("url") or "")
            meta = " · ".join(value for value in [str(item.get("source") or ""),
                                                  format_published_at(item.get("published_at"))] if value)
            events = item.get("events",[])
            title = events[0] if events else title.removeprefix("핵심 내용 · ")
            contents = item.get("contents",[])
            confirmed = format_confirmed_content(contents[0]) if contents else ""
            if len(confirmed)>180:
                confirmed = confirmed[:179].rstrip()+"…"
            description = f'<div class="source-confirmed"><strong>확인한 내용</strong>{escape(confirmed)}</div>' if detail and confirmed else ""
            keywords = "".join(f'<span class="source-keyword">{escape(event)}</span>' for event in events[1:]) if detail else ""
            topics = f'<div class="source-keywords">{keywords}</div>' if keywords else ""
            missing_link = '<div class="source-meta">원문 링크 미제공</div>' if detail and not url else ""
            title_row = f'<span class="source-card-title"><span class="kind">{label}</span>{escape(title)}</span><span class="source-inline-meta">{escape(meta)}</span>'
            if detail and urlparse(url).scheme in {"http","https"}:
                title_block = f'<a class="source-heading" href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer" aria-label="{escape(title,quote=True)} 원문 보기">{title_row}</a>'
            else:
                title_block = f'<div class="source-heading">{title_row}</div>'
            # Use raw HTML rendering so Markdown cannot split the card into
            # an empty anchor followed by separately bordered block elements.
            st.html(f'<div class="source-item">{title_block}{description}{topics}{missing_link}</div>')

def set_explanation_page(key,index):
    st.session_state[key] = index

@st.dialog("설명문 한 눈에 보기",width="large")
def explanation_dialog(name,day,paragraphs,market_warning):
    st.markdown(f'<div class="section-label">{escape(str(name))} · {dot(day)}</div>',unsafe_allow_html=True)
    if market_warning:
        st.warning(MARKET_ALERT_WARNING)
    text = "".join("<p>"+escape(paragraph).replace("\n","<br>")+"</p>" for paragraph in paragraphs)
    with st.container(height=520):
        st.markdown(f'<div class="summary-panel">{text}</div>',unsafe_allow_html=True)
    if st.button("닫기",key="close_explanation",width="stretch"):
        st.rerun()

def news_entry(row,day,scope):
    result = load_case_result(row,day)
    code = row["code"]
    paragraphs = result["paragraphs"]
    st.markdown('<div class="section-label">관련 뉴스·공시 요약</div>',unsafe_allow_html=True)
    market_warning = market_alert_active(row,day)
    if market_warning and paragraphs:
        st.warning(MARKET_ALERT_WARNING)
    for issue in result["issues"]:
        st.warning(issue)
    if paragraphs:
        page_key = f"explanation_page_{scope}_{code}_{day}"
        page = min(max(int(st.session_state.get(page_key,0)),0),len(paragraphs)-1)
        st.session_state[page_key] = page
        text = escape(paragraphs[page]).replace("\n","<br>")
        st.html(f'<div class="explanation-slide"><div class="explanation-label">문단 {page+1}</div>{text}</div>')
        with st.container(key=f"explanation_nav_{scope}_{code}"):
            previous,counter,following = st.columns([1,2,1],gap="small")
            with previous:
                st.button("← 이전",key=f"explanation_prev_{scope}_{code}",width="stretch",disabled=page==0,
                          on_click=set_explanation_page,args=(page_key,page-1))
            with counter:
                st.markdown(f'<div class="explanation-counter">{page+1} / {len(paragraphs)}</div>',unsafe_allow_html=True)
            with following:
                st.button("다음 →",key=f"explanation_next_{scope}_{code}",width="stretch",disabled=page==len(paragraphs)-1,
                          on_click=set_explanation_page,args=(page_key,page+1))
    else:
        st.markdown(f'<div class="placeholder">{RESULT_PENDING}</div>',unsafe_allow_html=True)
    overview,source_view = st.columns([1,2],gap="small")
    with overview:
        if st.button("한 눈에 보기",key=f"explanation_full_{scope}_{code}",width="stretch",disabled=not paragraphs):
            explanation_dialog(row["name"],day,paragraphs,market_warning)
    with source_view:
        st.button("출처 및 관련 뉴스 보기",key=f"news_summary_{scope}_{code}",width="stretch",
                  on_click=navigate,args=("news",code))

MARKET_ALERT_WARNING = "현재 시장 변동성이 평소보다 높은 수준입니다. 시장 전반의 비정상적인 움직임이 존재하므로 기업 고유 이상징후에 대한 해석에는 추가적인 주의가 필요합니다."

def parse_alert_flag(value):
    text = str(value).strip().lower()
    if text in {"true","1","1.0"}:
        return True
    if text in {"false","0","0.0"}:
        return False
    return None

def find_market_alert(payload):
    if isinstance(payload,dict):
        if "market_alert" in payload:
            flag = parse_alert_flag(payload["market_alert"])
            if flag is not None:
                return flag
        for value in payload.values():
            flag = find_market_alert(value)
            if flag is not None:
                return flag
    elif isinstance(payload,list):
        for value in payload:
            flag = find_market_alert(value)
            if flag is not None:
                return flag
    return None

def market_alert_active(row,day):
    # The matching case JSON is authoritative when its flag is present.
    folder = ROOT / "source_data" / "anormaly_result"
    for path in sorted(folder.glob(f"{day}_*.json")):
        subject = path.stem[len(day)+1:].strip()
        if subject not in {str(row["name"]).strip(),str(row["code"])}:
            continue
        try:
            flag = find_market_alert(json.loads(path.read_text(encoding="utf-8-sig")))
        except (OSError,ValueError):
            continue
        if flag is not None:
            return flag
    return parse_alert_flag(row.get("market_alert")) is True

def news_summary_page(row,day):
    parent = st.session_state.get("news_parent","list")
    back_label = {"detail":"종목 상세로","list":"경보 목록으로","themes":"테마 목록으로","favorites":"관심 종목으로"}.get(parent,"이전 화면으로")
    st.button(f"← {back_label}",key="news_back",on_click=return_from_news)
    st.markdown('<div class="page-title">핵심 정보</div>',unsafe_allow_html=True)
    with st.container(key=f"card_news_{row['code']}"):
        header(row,"news",clickable=False)
        st.markdown(f'<div class="date">{dot(day)} 정규장 마감 기준</div>',unsafe_allow_html=True)
        if market_alert_active(row,day):
            st.warning(MARKET_ALERT_WARNING)
        result = load_case_result(row,day)
        for issue in result["issues"]:
            st.warning(issue)
        sources(result["items"],row["code"],day,detail=True,heading="관련 뉴스·공시 핵심 정보")

def normalize_prices(raw):
    required = {"date","code","close"}
    if not required <= set(raw.columns):
        raise ValueError("종가 데이터에는 date, code, close 컬럼이 필요해요.")
    view = raw[["date","code","close"]].copy()
    view["date"] = pd.to_datetime(view["date"],errors="coerce").dt.strftime("%Y-%m-%d")
    view["code"] = view["code"].astype(str).str.strip().str.zfill(6)
    view["close"] = pd.to_numeric(view["close"],errors="coerce")
    view = view.dropna(subset=["date","close"])
    view = view[view["close"].gt(0)]
    if view.duplicated(["date","code"]).any():
        raise ValueError("종가 데이터에 같은 날짜·종목이 중복돼 있어요.")
    return view.sort_values(["code","date"]).reset_index(drop=True)

def normalize_volumes(raw):
    if not {"date","code","volume"} <= set(raw.columns):
        raise ValueError("거래량 데이터에는 date, code, volume 컬럼이 필요해요. 단위는 주예요.")
    view = raw[["date","code","volume"]].copy()
    view["date"] = pd.to_datetime(view["date"],errors="coerce").dt.strftime("%Y-%m-%d")
    view["code"] = view["code"].astype(str).str.strip().str.zfill(6)
    view["volume"] = pd.to_numeric(view["volume"],errors="coerce")
    view = view.dropna(subset=["date","volume"])
    view = view[view["volume"].ge(0)]
    if view.duplicated(["date","code"]).any():
        raise ValueError("거래량 데이터에 같은 날짜·종목이 중복돼 있어요.")
    return view.sort_values(["code","date"]).reset_index(drop=True)

def normalize_caps(raw):
    if not {"date","code","market_cap"} <= set(raw.columns):
        raise ValueError("시가총액 데이터에는 date, code, market_cap 컬럼이 필요해요. 금액은 원 단위예요.")
    view = raw[["date","code","market_cap"]].copy()
    view["date"] = pd.to_datetime(view["date"],errors="coerce").dt.strftime("%Y-%m-%d")
    view["code"] = view["code"].astype(str).str.strip().str.zfill(6)
    view["market_cap"] = pd.to_numeric(view["market_cap"],errors="coerce")
    view = view.dropna(subset=["date","market_cap"])
    view = view[view["market_cap"].gt(0)]
    if view.duplicated(["date","code"]).any():
        raise ValueError("시가총액 데이터에 같은 날짜·종목이 중복돼 있어요.")
    return view.sort_values(["date","code"]).reset_index(drop=True)

def read_supplement(path,normalizer):
    try:
        return normalizer(pd.read_csv(path,dtype={"code":str}))
    except (OSError,ValueError) as exc:
        st.warning(f"{path.name}: {exc}")
        return None

def get_price_data(raw_results):
    if "uploaded_prices" in st.session_state:
        return st.session_state.uploaded_prices
    for path in [DATA/"daily_prices.csv",DATA/"panel.csv",ROOT/"panel.csv"]:
        if path.is_file():
            result = read_supplement(path,normalize_prices)
            if result is not None:
                return result
    if "close" in raw_results:
        return normalize_prices(raw_results)
    return normalize_prices(pd.read_csv(StringIO(gzip.decompress(base64.b64decode(BUNDLED_PRICES)).decode("utf-8")),dtype={"code":str}))

def get_volume_data(raw_results):
    for path in [DATA/"daily_volumes.csv",ROOT/"daily_volumes.csv",DATA/"panel.csv",ROOT/"panel.csv"]:
        if path.is_file():
            result = read_supplement(path,normalize_volumes)
            if result is not None:
                return result
    if "volume" in raw_results:
        return normalize_volumes(raw_results)
    return normalize_volumes(pd.read_csv(StringIO(gzip.decompress(base64.b64decode(BUNDLED_VOLUMES)).decode("utf-8")),dtype={"code":str}))

def get_cap_data(raw_results):
    frames = []
    if "market_cap" in raw_results:
        frames.append(normalize_caps(raw_results))
    path = MARKET_CSV/"market_caps.csv"
    if path.is_file():
        result = read_supplement(path,normalize_caps)
        if result is not None:
            frames.append(result)
    if "uploaded_caps" in st.session_state:
        frames.append(st.session_state.uploaded_caps)
    if "fetched_caps" in st.session_state:
        frames.append(st.session_state.fetched_caps)
    if not frames:
        return pd.DataFrame(columns=["date","code","market_cap"])
    return pd.concat(frames,ignore_index=True).drop_duplicates(["date","code"],keep="last")

def attach_caps(records,caps,day):
    subset = caps[caps["date"].eq(day)][["code","market_cap"]]
    return records.drop(columns=["market_cap"],errors="ignore").merge(subset,on="code",how="left",validate="many_to_one")

def sort_stocks(records):
    if "market_cap" not in records:
        return records.sort_values("name",kind="stable")
    return records.sort_values(["market_cap","name"],ascending=[False,True],na_position="last",kind="stable")

def theme_overview(catalog,daily,day,show_title=True):
    fields = [field for field in ["code","date","stock_return","price_alert","volume_alert","decision_status"] if field in daily]
    records = catalog.merge(daily[fields],on="code",how="left",validate="one_to_one")
    valid = records["date"].notna()
    if "decision_status" in records:
        valid &= records["decision_status"].eq("OK")
    alert_count = int((valid & records["price_alert"].eq(True)).sum())
    volume_count = int((valid & records["volume_alert"].eq(True)).sum())
    favorite_count = len(st.session_state.favorites & set(catalog["code"]))
    missing_caps = int(catalog["market_cap"].isna().sum())
    order = "시가총액 크기 순" if not missing_caps else "시가총액 미연결 · 가나다순" if missing_caps==len(catalog) else f"시가총액 크기 순 · 시총 미연결 {missing_caps}개는 아래에 표시"
    title = '<div class="theme-overview-title">반도체</div>' if show_title else ""
    st.markdown(f'<div class="theme-overview">{title}<div class="theme-overview-date">{dot(day)} 정규장 마감 기준 · {order}</div><div class="theme-counts"><span class="theme-count">분석 대상<strong>{len(catalog)}개</strong></span><span class="theme-count">관심 종목<strong>{favorite_count}개</strong></span><span class="theme-count alert">주가 경보<strong>{alert_count}개</strong></span><span class="theme-count alert">거래량 경보<strong>{volume_count}개</strong></span></div><div class="theme-overview-note">경보 수는 전체 분석 대상 기준이며, 두 경보가 함께 발생한 종목은 각각 집계해요. 하트로 관심 종목을 선택하세요.</div></div>',unsafe_allow_html=True)

def closing_chart(prices,code,day):
    st.markdown('<div class="section-label">최근 20거래일 종가</div>',unsafe_allow_html=True)
    history = prices[prices["code"].eq(code)&prices["date"].le(day)].tail(20).copy()
    if history.empty:
        st.markdown('<div class="placeholder">종가 데이터를 연결해주세요.<br>선택한 날짜까지의 종가 데이터가 필요해요.</div>',unsafe_allow_html=True)
        return
    history["거래일"] = history["date"]
    history["종가 (원)"] = history["close"]
    order = history["거래일"].tolist()
    ticks = order[::4]
    chart = alt.Chart(history).mark_line(color="#8066df",strokeWidth=2.7,point=True).encode(
        x=alt.X("거래일:O",sort=order,title=None,
            axis=alt.Axis(values=ticks,labelExpr="substring(datum.label, 5, 7) + '/' + substring(datum.label, 8, 10)",labelAngle=0,grid=False)),
        y=alt.Y("종가 (원):Q",title=None,scale=alt.Scale(zero=False),axis=alt.Axis(format=",.0f")),
        tooltip=[alt.Tooltip("거래일:O",title="거래일"),alt.Tooltip("종가 (원):Q",format=",.0f")]
    ).properties(height=190)
    st.markdown('<div class="chart-axis-label">종가 (원)</div>',unsafe_allow_html=True)
    render_chart(emphasize_last_point(chart,history,"종가 (원)","원"))
    latest = history.iloc[-1]
    st.caption(f"{dot(history.iloc[0]['date'])} ~ {dot(latest['date'])} · {len(history)}거래일 · 날짜 눈금 4거래일 간격")
    if latest["date"] != day:
        st.caption(f"선택 기준일의 종가가 없어 확보된 마지막 거래일 {dot(latest['date'])}까지 표시해요.")
    if len(history)<20:
        st.caption("확보된 데이터가 20거래일보다 적어요.")

def volume_chart(volumes,df,code,day,show_z=True):
    st.markdown('<div class="section-label">최근 20거래일 거래량</div>',unsafe_allow_html=True)
    history = volumes[volumes["code"].eq(code)&volumes["date"].le(day)].tail(20).copy()
    if history.empty:
        st.caption("선택 기준일까지 표시할 거래량 데이터가 없어요.")
    else:
        history["거래일"] = history["date"]
        history["거래량 (주)"] = history["volume"]
        order = history["거래일"].tolist()
        chart = alt.Chart(history).mark_bar(color="#10b981",cornerRadiusTopLeft=3,cornerRadiusTopRight=3).encode(
            x=alt.X("거래일:O",sort=order,title=None,
                axis=alt.Axis(values=order[::4],labelExpr="substring(datum.label, 5, 7) + '/' + substring(datum.label, 8, 10)",labelAngle=0,grid=False)),
            y=alt.Y("거래량 (주):Q",title=None,scale=alt.Scale(zero=True),axis=alt.Axis(format=",.0f")),
            tooltip=[alt.Tooltip("거래일:O"),alt.Tooltip("거래량 (주):Q",format=",.0f")]
        ).properties(height=190)
        st.markdown('<div class="chart-axis-label">거래량 (주)</div>',unsafe_allow_html=True)
        render_chart(emphasize_last_point(chart,history,"거래량 (주)","주",color="#059669",label_color="#047857"))
        st.caption(f"{dot(order[0])} ~ {dot(order[-1])} · {len(history)}거래일 · 날짜 눈금 4거래일 간격")
        if order[-1]!=day:
            st.caption(f"선택 기준일의 거래량이 없어 확보된 마지막 거래일 {dot(order[-1])}까지 표시해요.")
        if len(history)<20:
            st.caption("확보된 거래량 데이터가 20거래일보다 적어요.")
    if not show_z:
        return
    st.markdown('<div class="section-label">거래량 Z점수 추이</div>',unsafe_allow_html=True)
    history = df[df["code"].eq(code)&df["date"].le(day)].tail(20).copy()
    if "volume_z" not in history or not history["volume_z"].notna().any():
        st.caption("거래량 Z점수 분석 결과가 없어요.")
        return
    history["거래일"] = history["date"]
    history["거래량 Z점수"] = history["volume_z"]
    order = history["거래일"].tolist()
    chart = alt.Chart(history).mark_line(color="#10b981",strokeWidth=2.7,point=True).encode(
        x=alt.X("거래일:O",sort=order,title=None,
            axis=alt.Axis(values=order[::4],labelExpr="substring(datum.label, 5, 7) + '/' + substring(datum.label, 8, 10)",labelAngle=0,grid=False)),
        y=alt.Y("거래량 Z점수:Q",title=None,scale=alt.Scale(zero=True),axis=alt.Axis(format="+.2f")),
        tooltip=[alt.Tooltip("거래일:O"),alt.Tooltip("거래량 Z점수:Q",format="+.2f"),alt.Tooltip("volume_alert:N",title="FDS 거래량 경보")]
    ).properties(height=190)
    threshold = alt.Chart(pd.DataFrame({"임계값":[Z_THRESHOLD]})).mark_rule(color="#6bbba4",strokeDash=[5,4]).encode(y="임계값:Q",tooltip=[alt.Tooltip("임계값:Q")])
    st.markdown('<div class="chart-axis-label">거래량 Z점수</div>',unsafe_allow_html=True)
    render_chart(emphasize_last_point(chart,history,"거래량 Z점수","",color="#059669",label_color="#047857")+threshold)
    st.caption(f"{dot(order[0])} ~ {dot(order[-1])} · {len(history)}거래일 · 날짜 눈금 4거래일 간격")
    st.caption("점선은 거래량 Z점수 +2.5 기준선이에요.")

def alert_records(selected):
    return sort_stocks(selected[selected["price_alert"] | selected["volume_alert"]])

