    st.subheader(f"검색 결과 {len(matched)}개")
    st.markdown(f'<div class="date">{dot(st.session_state.analysis_date)} 정규장 마감 기준</div>',unsafe_allow_html=True)
    if matched.empty:
        st.info("일치하는 분석 대상 종목이 없어요. 현재는 반도체 6개 종목을 검색할 수 있어요.")
